def flatten(d):
    """Flatten nested dicts/lists into a single-level dict with dot-joined keys.

    List indices become key segments, e.g. {"a": {"b": [7]}} -> {"a.b.0": 7}.
    Empty containers contribute no keys.
    """
    out = {}

    def _walk(value, path):
        if isinstance(value, dict):
            for key, val in value.items():
                _walk(val, path + [str(key)])
        elif isinstance(value, list):
            for idx, val in enumerate(value):
                _walk(val, path + [str(idx)])
        elif path:
            out[".".join(path)] = value

    _walk(d, [])
    return out
```

