def flatten(d):
    """Flatten nested dicts/lists into a single-level dict with dot-joined keys.

    List indices become key segments, e.g. {"a": {"b": [7]}} -> {"a.b.0": 7}.
    Empty containers contribute no keys.
    """
    result = {}

    def _walk(node, path):
        if isinstance(node, dict):
            for key, value in node.items():
                segment = str(key)
                _walk(value, f"{path}.{segment}" if path else segment)
        elif isinstance(node, list):
            for index, value in enumerate(node):
                _walk(value, f"{path}.{index}" if path else str(index))
        else:
            result[path] = node

    _walk(d, "")
    return result
```

