def closest_pair(nums, target):
    """
    Return the indices (i, j), i < j, of the two elements in nums whose
    sum is closest to target. On equal closeness, the pair with the
    smallest i (then smallest j) is returned.
    """
    n = len(nums)
    if n < 2:
        return None

    best_i, best_j = 0, 1
    best_diff = abs(nums[0] + nums[1] - target)

    for i in range(n - 1):
        for j in range(i + 1, n):
            diff = abs(nums[i] + nums[j] - target)
            if diff < best_diff:
                best_diff = diff
                best_i, best_j = i, j

    return (best_i, best_j)
```

