def roman_to_int(s):
    """Convert a standard Roman numeral string (up to thousands) to an integer.

    Supports subtractive notation (e.g. IV=4, IX=9, XL=40, XC=90, CD=400, CM=900).
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        v = values[ch]
        # If a smaller value precedes a larger one, it was subtracted (subtractive notation)
        if i + 1 < len(s) and v < values[s[i + 1]]:
            total -= v
        else:
            total += v
    return total
```

