def parse_csv(line, delim=','):
    fields = []
    buf = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    buf.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                buf.append(ch)
                i += 1
        elif ch == '"' and not buf:
            in_quotes = True
            i += 1
        elif ch == delim:
            fields.append(''.join(buf))
            buf = []
            i += 1
        else:
            buf.append(ch)
            i += 1
    fields.append(''.join(buf))
    return fields
```

