def search_rotated(nums, target):
    """
    Search for `target` in a sorted-then-rotated array of distinct integers.

    Returns the index of `target`, or -1 if it is not present.
    Runs in O(log n) time and O(1) space.
    """
    lo, hi = 0, len(nums) - 1

    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid

        # Is the left half [lo..mid] sorted?
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        # Otherwise the right half [mid..hi] must be sorted.
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1

    return -1
```

