class MinStack:
    """A stack supporting push, pop, top, and get_min, all in O(1) time.

    pop/top/get_min are only called when the stack is non-empty.
    """

    def __init__(self):
        # Each entry is a tuple (value, minimum_value_in_stack_at_this_point).
        self._data = []

    def push(self, x):
        if not self._data:
            current_min = x
        else:
            current_min = x if x < self._data[-1][1] else self._data[-1][1]
        self._data.append((x, current_min))

    def pop(self):
        self._data.pop()

    def top(self):
        return self._data[-1][0]

    def get_min(self):
        return self._data[-1][1]
