def edit_distance(a, b):
    # Handle empty inputs quickly.
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

    # prev[j] = edit distance between a[:i] and b[:j] for the previous row.
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        curr = [i]  # distance between a[:i] and b[:0] is i deletions
        for j, cb in enumerate(b, 1):
            cost = 0 if ca == cb else 1
            curr.append(min(
                prev[j] + 1,      # deletion from a
                curr[j - 1] + 1,  # insertion into a
                prev[j - 1] + cost,  # substitution (or match)
            ))
        prev = curr
    return prev[-1]
```

