def coin_change(coins, amount):
    """
    Return the fewest number of coins (unlimited supply) needed to make up
    `amount`, or -1 if it cannot be made.
    """
    if amount == 0:
        return 0

    coins = [c for c in coins if c > 0]
    if not coins:
        return -1

    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for c in coins:
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1

    return dp[amount] if dp[amount] != INF else -1
```

