    """Return the fewest coins needed to make up `amount` (unlimited supply), or -1 if impossible."""
    if amount < 0:
        return -1

    # dp[i] = fewest coins to make amount i; amount + 1 acts as "infinity".
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if 0 < coin <= i:
                if dp[i - coin] + 1 < dp[i]:
                    dp[i] = dp[i - coin] + 1

    return dp[amount] if dp[amount] <= amount else -1
