def is_balanced_code(s):
    """Check whether brackets (), [], {} in pseudo-code s are balanced,
    ignoring brackets inside single- or double-quoted string literals.
    Inside a literal a backslash escapes the next character; an
    unterminated literal swallows the rest of the input."""
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    openers = '([{'
    closers = ')]}'
    i = 0
    n = len(s)
    quote = None  # None, "'", or '"'
    while i < n:
        c = s[i]
        if quote is None:
            if c in openers:
                stack.append(c)
            elif c in closers:
                if not stack or stack[-1] != matching[c]:
                    return False
                stack.pop()
            elif c == "'":
                quote = "'"
            elif c == '"':
                quote = '"'
        else:
            if c == '\\':
                i += 2  # escape: skip the escaped character
                continue
            if c == quote:
                quote = None
        i += 1
    return len(stack) == 0
