def interval_overlap_count(intervals):
    events = {}
    for start, end in intervals:
        if start > end:
            raise ValueError("interval start must not be greater than end")
        events[start] = events.get(start, 0) + 1
        events[end + 1] = events.get(end + 1, 0) - 1
    current = 0
    best = 0
    for coord in sorted(events):
        current += events[coord]
        if current > best:
            best = current
    return best
```

