def decode_escaped_fields(s):
    fields = []
    current = []
    escaping = False
    for ch in s:
        if escaping:
            current.append(ch)
            escaping = False
        elif ch == '\\':
            escaping = True
        elif ch == ',':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaping:
        raise ValueError("trailing unmatched backslash")
    fields.append(''.join(current))
    return fields
