from collections import deque


def longest_bounded_window(nums, limit):
    if limit < 0 or not nums:
        return 0

    min_deque = deque()  # increasing: front is the window minimum
    max_deque = deque()  # decreasing: front is the window maximum
    left = 0
    best = 0

    for right, x in enumerate(nums):
        while min_deque and min_deque[-1] > x:
            min_deque.pop()
        min_deque.append(x)
        while max_deque and max_deque[-1] < x:
            max_deque.pop()
        max_deque.append(x)

        while max_deque[0] - min_deque[0] > limit:
            if nums[left] == min_deque[0]:
                min_deque.popleft()
            if nums[left] == max_deque[0]:
                max_deque.popleft()
            left += 1

        window = right - left + 1
        if window > best:
            best = window

    return best
```

