def longest_bounded_window(nums, limit):
    if not nums or limit < 0:
        return 0

    min_deque = deque()  # indices, values increasing
    max_deque = deque()  # indices, values decreasing
    left = 0
    best = 0

    for right, x in enumerate(nums):
        while min_deque and nums[min_deque[-1]] >= x:
            min_deque.pop()
        min_deque.append(right)

        while max_deque and nums[max_deque[-1]] <= x:
            max_deque.pop()
