from collections import deque


def longest_bounded_window(nums, limit):
    """Return the length of the longest contiguous subarray whose
    max - min <= limit. Empty input or a negative limit yields 0."""
    if limit < 0 or not nums:
        return 0

    max_deque = deque()  # indices with non-increasing values (front is window max)
    min_deque = deque()  # indices with non-decreasing values (front is window min)
    left = 0
    best = 0

    for right, value in enumerate(nums):
        while max_deque and nums[max_deque[-1]] <= value:
            max_deque.pop()
        max_deque.append(right)

        while min_deque and nums[min_deque[-1]] >= value:
            min_deque.pop()
        min_deque.append(right)

        while nums[max_deque[0]] - nums[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        window_len = right - left + 1
        if window_len > best:
            best = window_len

    return best
```

