from math import gcd


def fraction_add(a, b):
    """Return the sum of two rational numbers given as (numerator, denominator)
    pairs, reduced to lowest terms with a positive denominator."""
    n1, d1 = a
    n2, d2 = b

    if d1 == 0 or d2 == 0:
        raise ValueError("Denominators must be nonzero")

    num = n1 * d2 + n2 * d1
    den = d1 * d2

    # Normalize so the denominator is positive.
    if den < 0:
        num, den = -num, -den

    if num == 0:
        return (0, 1)

    g = gcd(abs(num), den)
    return (num // g, den // g)
