import heapq

def merge_sorted_streams(streams):
    heap = []
    for i, s in enumerate(streams):
        if s:
            heapq.heappush(heap, (s[0], i, 0))
    result = []
    while heap:
        val, s_idx, e_idx = heapq.heappop(heap)
        result.append(val)
        next_idx = e_idx + 1
        if next_idx < len(streams[s_idx]):
            heapq.heappush(heap, (streams[s_idx][next_idx], s_idx, next_idx))
    return result
