from collections import deque


def shortest_path_with_count(n, edges, source, target):
    if source == target:
        return (0, 1)

    # Build adjacency list, ignoring duplicate edges.
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    dist = [-1] * n
    count = [0] * n
    dist[source] = 0
    count[source] = 1

    queue = deque([source])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                # First time reaching v: it's one step further than u.
                dist[v] = dist[u] + 1
                count[v] = count[u]
                queue.append(v)
            elif dist[v] == dist[u] + 1:
                # v already reached at this BFS level: another shortest path.
                count[v] += count[u]

    if dist[target] == -1:
        return (-1, 0)
    return (dist[target], count[target])
```

