        adj[u].add(v)
        adj[v].add(u)
    adj = [list(s) for s in adj]

    dist = [-1] * n
    count = [0] * n
    dist[source] = 0
    count[source] = 1

    queue = deque([source])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                count[v] = count[u]
                queue.append(v)
            elif dist[v] == dist[u] + 1:
                count[v] += count[u]

    if dist[target] == -1:
        return (-1, 0)
    return (dist[target], count[target])
