from collections import deque


def shortest_path_with_count(n, edges, source, target):
    if source == target:
        return (0, 1)

    # Build adjacency lists, ignoring duplicate edges (order-independent).
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    adj = [list(s) for s in adj]

    dist = [-1] * n
    count = [0] * n
    dist[source] = 0
    count[source] = 1

    dq = deque([source])
    while dq:
        u = dq.popleft()
        nd = dist[u] + 1
        uc = count[u]
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = nd
                count[v] = uc
                dq.append(v)
            elif dist[v] == nd:
                count[v] += uc

    if dist[target] == -1:
        return (-1, 0)
    return (dist[target], count[target])
