def normalize_path(path):
    """Normalize an absolute Unix-style path.

    - Collapses repeated slashes.
    - Removes '.' components.
    - Resolves '..' by dropping the preceding ordinary component,
      staying at root if there is none.
    - Returns '/' when no components remain.
    - Backslashes are treated as ordinary characters, not separators.
    """
    components = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if components:
                components.pop()
        else:
            components.append(part)
    return '/' + '/'.join(components)
